const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}` };
const today = new Date().toISOString().split('T')[0];
const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

const fetch = async (url) => {
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers });
  return resp;
};

const [ventas, cotizaciones, compras, pipelineDelayed, unreadEmails, coiErrors, insightsWarning] = await Promise.all([
  fetch(`${supabaseUrl}/rest/v1/ventas?select=id,folio,total,estatus_pago&created_at=gte.${yesterday}&created_at=lt.${today}`),
  fetch(`${supabaseUrl}/rest/v1/cotizaciones?select=id,folio,total,estado&created_at=gte.${yesterday}&created_at=lt.${today}`),
  fetch(`${supabaseUrl}/rest/v1/compras?select=id,folio,total,estado&created_at=gte.${yesterday}&created_at=lt.${today}`),
  fetch(`${supabaseUrl}/rest/v1/ssepi_folio_operativo?select=id,etapa,updated_at&etapa=not.in.(finalizado,facturado_timbrado)&updated_at=lt.${new Date(Date.now() - 3*86400000).toISOString()}`),
  fetch(`${supabaseUrl}/rest/v1/inbound_emails?select=id&leido=eq.false`),
  fetch(`${supabaseUrl}/rest/v1/coi_sync_queue?select=id,erp_source,folio&status=eq.error`),
  fetch(`${supabaseUrl}/rest/v1/n8n_insights?select=id,workflow_name,summary,severity&severity=in.(warning,critical)&dismissed=eq.false&created_at=gte.${yesterday}`)
]);

return [{ json: {
  date: today,
  ventas_new: ventas.length,
  ventas_total: ventas.reduce((s, v) => s + (v.total || 0), 0),
  cotizaciones_new: cotizaciones.length,
  compras_new: compras.length,
  pipeline_delayed: pipelineDelayed.length,
  unread_emails: unreadEmails.length,
  coi_errors: coiErrors.length,
  insights_warning: insightsWarning.length,
  insights_detail: insightsWarning.slice(0, 5)
} }];

const resp = $input.item.json;
const content = resp.message?.content || resp.content || resp.text || '';
return [{ json: { text: content, content: content } }];
